INSERT INTO personal_transactions (
	user_num, category_num, account_num, trans_type,
	trans_amount, trans_date, trans_memo
)	
VALUES (
	#{userNum}, #{categoryNum}, #{accountNum}, #{transType}, 
	#{transAmount}, #{transDate}, #{transMemo}
)

mapper.select:
SELECT t.trans_num, t.version, t.trans_amount, t.trans_date, t.trans_memo, t.trans_type, t.category_num, c.category_name, c.category_emoji, t.account_num, a.account_name FROM personal_transactions t JOIN personal_categories c ON t.category_num = c.category_num LEFT JOIN accounts a ON t.account_num = a.account_num WHERE t.user_num = #{userNum} AND t.use_yn = 'Y'
AND t.trans_date >= #{startDate} AND t.trans_date < #{endDate}
ORDER BY t.trans_date DESC, t.trans_num ASC

mapper.update:
UPDATE personal_transactions
SET use_yn = 'N', version = version + 1
WHERE trans_num = #{transNum}
  AND version = #{version}
  AND use_yn = 'Y'
